class TriggersResource(Group):
    """client.triggers: one method per operation."""

    def create(self, body: CreateTriggerBody, *, idempotency_key: str | None = None, timeout: float | None = None) -> CreateTriggerResponse:
        """Make a trigger: a schedule or a signed webhook that starts a capped run of an agent, or messages a run (POST /triggers)."""
        return self._call("createTrigger", (), body, {"Idempotency-Key": idempotency_key}, timeout=timeout)

    def delete(self, trigger_id: str, *, timeout: float | None = None) -> None:
        """Delete a trigger and its firings; the runs it started stay (DELETE /triggers/{trigger_id})."""
        return self._call("deleteTrigger", (trigger_id,), None, None, timeout=timeout)

    def fire(self, trigger_id: str, *, idempotency_key: str | None = None, timeout: float | None = None) -> FireTriggerResponse:
        """Run it now: one firing per Idempotency-Key (POST /triggers/{trigger_id}/fire)."""
        return self._call("fireTrigger", (trigger_id,), None, {"Idempotency-Key": idempotency_key}, timeout=timeout)

    def firings(self, trigger_id: str, *, timeout: float | None = None) -> ListTriggerFiringsResponse:
        """The trigger's last 200 firings, newest first (GET /triggers/{trigger_id}/firings)."""
        return self._call("listTriggerFirings", (trigger_id,), None, None, timeout=timeout)

    def get(self, trigger_id: str, *, timeout: float | None = None) -> GetTriggerResponse:
        """One trigger (GET /triggers/{trigger_id})."""
        return self._call("getTrigger", (trigger_id,), None, None, timeout=timeout)

    def list(self, *, timeout: float | None = None) -> ListTriggersResponse:
        """The triggers: schedules and signed webhooks that start an agent's capped runs or message a run (GET /triggers)."""
        return self._call("listTriggers", (), None, None, timeout=timeout)

    def rotate_secret(self, trigger_id: str, *, timeout: float | None = None) -> RotateTriggerSecretResponse:
        """A webhook trigger's new secret, shown once; the old one signs nothing from now on (POST /triggers/{trigger_id}/secret)."""
        return self._call("rotateTriggerSecret", (trigger_id,), None, None, timeout=timeout)

    def update(self, trigger_id: str, body: UpdateTriggerBody, *, timeout: float | None = None) -> UpdateTriggerResponse:
        """Change a trigger, or turn it off and on (PATCH /triggers/{trigger_id})."""
        return self._call("updateTrigger", (trigger_id,), body, None, timeout=timeout)


class WebhookResource(Group):
    """client.webhook: one method per operation."""

    def delete(self, *, timeout: float | None = None) -> None:
        """Remove the webhook; its pending messages are dropped, the log of attempts is kept (DELETE /settings/webhook)."""
        return self._call("deleteWebhook", (), None, None, timeout=timeout)

    def deliveries(self, *, timeout: float | None = None) -> ListWebhookDeliveriesResponse:
        """The last 50 attempts, newest first (GET /settings/webhook/deliveries)."""
        return self._call("listWebhookDeliveries", (), None, None, timeout=timeout)

    def get(self, *, timeout: float | None = None) -> GetWebhookResponse:
        """The webhook this server POSTs run notices to, if one is set; never its secret (GET /settings/webhook)."""
        return self._call("getWebhook", (), None, None, timeout=timeout)

    def redeliver(self, webhook_id: str, *, timeout: float | None = None) -> RedeliverWebhookResponse:
        """Send a message of the log again, once now, under the same webhook-id and body (POST /settings/webhook/deliveries/{webhook_id}/redeliver)."""
        return self._call("redeliverWebhook", (webhook_id,), None, None, timeout=timeout)

    def save(self, body: SaveWebhookBody, *, timeout: float | None = None) -> SaveWebhookResponse:
        """Set the webhook's URL (PUT /settings/webhook)."""
        return self._call("saveWebhook", (), body, None, timeout=timeout)

    def test(self, *, timeout: float | None = None) -> TestWebhookResponse:
        """Send a `webhook.test` message now, once, and say how it went (POST /settings/webhook/test)."""
        return self._call("testWebhook", (), None, None, timeout=timeout)


